class Solution {
public:
    int maximalSquare(vector<vector<char>>& matrix) {
        if (matrix.empty() || matrix[0].empty()) return 0;
        int m = matrix.size(), n = matrix[0].size();
        vector<int> dp(n + 1, 0);
        int maxSide = 0, prev = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                int temp = dp[c + 1];
                if (matrix[r][c] == '1') {
                    dp[c + 1] = min({dp[c], dp[c + 1], prev}) + 1;
                    maxSide = max(maxSide, dp[c + 1]);
                } else {
                    dp[c + 1] = 0;
                }
                prev = temp;
            }
        }
        return maxSide * maxSide;
    }
};

class Solution {
    public int maximalSquare(char[][] matrix) {
        if (matrix == null || matrix.length == 0) return 0;
        int m = matrix.length, n = matrix[0].length;
        int[] dp = new int[n + 1];
        int maxSide = 0, prev = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int temp = dp[c + 1];
                if (matrix[r][c] == '1') {
                    dp[c + 1] = Math.min(Math.min(dp[c], dp[c + 1]), prev) + 1;
                    maxSide = Math.max(maxSide, dp[c + 1]);
                } else {
                    dp[c + 1] = 0;
                }
                prev = temp;
            }
        }
        return maxSide * maxSide;
    }
}

var maximalSquare = function(matrix) {
    if (!matrix || matrix.length === 0) return 0;
    const m = matrix.length, n = matrix[0].length;
    const dp = new Array(n + 1).fill(0);
    let maxSide = 0, prev = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const temp = dp[c + 1];
            if (matrix[r][c] === '1') {
                dp[c + 1] = Math.min(dp[c], dp[c + 1], prev) + 1;
                maxSide = Math.max(maxSide, dp[c + 1]);
            } else {
                dp[c + 1] = 0;
            }
            prev = temp;
        }
    }
    return maxSide * maxSide;
};
